-- AdmitAtlas P1 schema — portable DDL (H2 2.x AND MySQL 8.0)
-- Deliberately avoids MySQL-only syntax (ENGINE / PARTITION / COMMENT / JSON column /
-- inline KEY): dev runs on an embedded H2 file DB, prod on MySQL 8.
-- MySQL-optimised partitioned DDL is kept separately in sql/V1__init.sql.
--
-- Conventions:
--   * min_rank (省排名) is the ONLY field used for cross-year comparison.
--   * every fact row carries data_version + source_url + audit_status (留证与审核).
--   * IDs are generated by the application so the DDL works on both engines.
--   * JSON columns are stored as VARCHAR text and parsed by Jackson.

CREATE TABLE dim_province (
  province_code  VARCHAR(6)  NOT NULL,
  province_name  VARCHAR(64) NOT NULL,
  exam_mode      VARCHAR(24) NOT NULL,
  policy_version VARCHAR(32),
  PRIMARY KEY (province_code)
);

CREATE TABLE dim_school (
  school_code   VARCHAR(10)  NOT NULL,
  school_name   VARCHAR(128) NOT NULL,
  supervisor    VARCHAR(128),
  province_code VARCHAR(6),
  city          VARCHAR(64),
  tier_tags     VARCHAR(128),
  school_type   VARCHAR(32),
  school_level  VARCHAR(32),
  intro         VARCHAR(2000),
  PRIMARY KEY (school_code)
);
CREATE INDEX idx_school_province ON dim_school (province_code);

CREATE TABLE dim_major (
  major_code   VARCHAR(16)  NOT NULL,
  major_name   VARCHAR(128) NOT NULL,
  category     VARCHAR(64),
  major_class  VARCHAR(64),
  degree_years SMALLINT,
  PRIMARY KEY (major_code)
);
CREATE INDEX idx_major_category ON dim_major (category);

CREATE TABLE dim_subject_requirement (
  req_code VARCHAR(24)  NOT NULL,
  req_name VARCHAR(128) NOT NULL,
  req_expr VARCHAR(256),
  PRIMARY KEY (req_code)
);

CREATE TABLE fact_admission_plan (
  id            BIGINT      NOT NULL,
  province_code VARCHAR(6)  NOT NULL,
  exam_year     SMALLINT    NOT NULL,
  category      VARCHAR(16) NOT NULL,
  batch         VARCHAR(16) NOT NULL,
  school_code   VARCHAR(10) NOT NULL,
  group_code    VARCHAR(32),
  major_code    VARCHAR(16),
  req_code      VARCHAR(24),
  plan_count    INT,
  data_version  VARCHAR(32) NOT NULL,
  source_url    VARCHAR(512),
  audit_status  SMALLINT    NOT NULL DEFAULT 0,
  created_at    DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);
CREATE INDEX idx_plan_lookup ON fact_admission_plan (province_code, exam_year, category, school_code);
CREATE INDEX idx_plan_version ON fact_admission_plan (data_version, audit_status);

CREATE TABLE fact_admission_score (
  id            BIGINT      NOT NULL,
  province_code VARCHAR(6)  NOT NULL,
  exam_year     SMALLINT    NOT NULL,
  category      VARCHAR(16) NOT NULL,
  batch         VARCHAR(16) NOT NULL,
  school_code   VARCHAR(10) NOT NULL,
  group_code    VARCHAR(32),
  major_code    VARCHAR(16),
  unit_name     VARCHAR(128),
  min_score     SMALLINT    NOT NULL,
  min_rank      INT         NOT NULL,
  avg_score     SMALLINT,
  max_score     SMALLINT,
  plan_count    INT,
  actual_count  INT,
  data_version  VARCHAR(32) NOT NULL,
  source_url    VARCHAR(512) NOT NULL,
  source_hash   VARCHAR(64),
  audit_status  SMALLINT    NOT NULL DEFAULT 0,
  created_at    DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);
-- 核心索引：候选检索按 (省, 年, 科类, 批次, 位次区间) 命中，不在应用层全量过滤
CREATE INDEX idx_query ON fact_admission_score (province_code, exam_year, category, batch, min_rank);
CREATE INDEX idx_school_year ON fact_admission_score (school_code, exam_year);
CREATE INDEX idx_score_version ON fact_admission_score (data_version, audit_status);

CREATE TABLE fact_score_segment (
  id               BIGINT      NOT NULL,
  province_code    VARCHAR(6)  NOT NULL,
  exam_year        SMALLINT    NOT NULL,
  category         VARCHAR(16) NOT NULL,
  score            SMALLINT    NOT NULL,
  segment_count    INT         NOT NULL DEFAULT 0,
  cumulative_count INT         NOT NULL,
  data_version     VARCHAR(32) NOT NULL,
  source_url       VARCHAR(512),
  PRIMARY KEY (id),
  CONSTRAINT uk_segment UNIQUE (province_code, exam_year, category, score)
);
CREATE INDEX idx_segment_score ON fact_score_segment (province_code, exam_year, category, score);

CREATE TABLE fact_batch_line (
  id            BIGINT      NOT NULL,
  province_code VARCHAR(6)  NOT NULL,
  exam_year     SMALLINT    NOT NULL,
  category      VARCHAR(16) NOT NULL,
  batch         VARCHAR(16) NOT NULL,
  line_score    SMALLINT    NOT NULL,
  data_version  VARCHAR(32) NOT NULL,
  source_url    VARCHAR(512),
  PRIMARY KEY (id),
  CONSTRAINT uk_line UNIQUE (province_code, exam_year, category, batch)
);

CREATE TABLE rule_policy (
  id                BIGINT      NOT NULL,
  province_code     VARCHAR(6)  NOT NULL,
  exam_year         SMALLINT    NOT NULL,
  exam_mode         VARCHAR(24) NOT NULL,
  volunteer_unit    VARCHAR(24) NOT NULL,
  volunteer_count   INT         NOT NULL,
  group_major_count INT,
  batches           VARCHAR(256),
  sort_fields       VARCHAR(1000),
  subject_rules     VARCHAR(2000),
  effective_from    VARCHAR(32),
  data_version      VARCHAR(32) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uk_policy UNIQUE (province_code, exam_year)
);

CREATE TABLE student_profile (
  id            BIGINT      NOT NULL,
  username      VARCHAR(64) NOT NULL,
  password_hash VARCHAR(256) NOT NULL,
  province_code VARCHAR(6),
  user_role     VARCHAR(24) NOT NULL DEFAULT 'STUDENT',
  created_at    DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT uk_username UNIQUE (username)
);

CREATE TABLE student_score (
  id             BIGINT      NOT NULL,
  user_id        BIGINT      NOT NULL,
  province_code  VARCHAR(6)  NOT NULL,
  exam_year      SMALLINT    NOT NULL,
  exam_mode      VARCHAR(24) NOT NULL,
  category       VARCHAR(16) NOT NULL,
  subject_combo  VARCHAR(1000),
  total_score    SMALLINT    NOT NULL,
  subject_scores VARCHAR(2000),
  rank_value     INT,
  rank_estimated SMALLINT    NOT NULL DEFAULT 0,
  created_at     DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);
CREATE INDEX idx_student_score ON student_score (user_id, exam_year);

CREATE TABLE student_preference (
  id             BIGINT      NOT NULL,
  user_id        BIGINT      NOT NULL,
  regions        VARCHAR(1000),
  major_keywords VARCHAR(1000),
  school_tiers   VARCHAR(1000),
  priority       VARCHAR(24),
  PRIMARY KEY (id),
  CONSTRAINT uk_user UNIQUE (user_id)
);

CREATE TABLE match_task (
  task_id        VARCHAR(40) NOT NULL,
  user_id        BIGINT      NOT NULL,
  province_code  VARCHAR(6)  NOT NULL,
  exam_year      SMALLINT    NOT NULL,
  task_status    VARCHAR(24) NOT NULL,
  input_snapshot VARCHAR(4000),
  data_version   VARCHAR(32),
  created_at     DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (task_id)
);
CREATE INDEX idx_task_user ON match_task (user_id, created_at);

CREATE TABLE suggestion_plan (
  plan_id         BIGINT      NOT NULL,
  user_id         BIGINT      NOT NULL,
  task_id         VARCHAR(40),
  plan_name       VARCHAR(128),
  volunteer_unit  VARCHAR(24),
  volunteer_count INT,
  data_version    VARCHAR(32),
  created_at      DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (plan_id)
);
CREATE INDEX idx_plan_user ON suggestion_plan (user_id);

CREATE TABLE suggestion_item (
  id                  BIGINT      NOT NULL,
  plan_id             BIGINT      NOT NULL,
  position_no         INT         NOT NULL,
  school_code         VARCHAR(10) NOT NULL,
  school_name         VARCHAR(128),
  group_or_major_code VARCHAR(32),
  unit_name           VARCHAR(128),
  tier                VARCHAR(16) NOT NULL,
  match_score         SMALLINT    NOT NULL,
  history_min_rank    INT,
  reason              VARCHAR(1000),
  PRIMARY KEY (id),
  CONSTRAINT uk_plan_position UNIQUE (plan_id, position_no)
);
CREATE INDEX idx_item_plan ON suggestion_item (plan_id, position_no);
